def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add single quote and skip both
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # skip the comma
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field - runs to next comma or end of line
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain double quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))
            if i < len(line):
                i += 1  # skip the comma

    return fields

